using System;
using System.Collections.Generic;
using System.Drawing;
using System.Globalization;
using System.IO;
using System.Windows.Forms;
namespace CircuitoStudio {
 public sealed class WizardSourceEditor:UserControl {
  readonly SourceSettings source;readonly TableLayoutPanel table=new TableLayoutPanel();readonly ComboBox model=new ComboBox(),basis=new ComboBox(),upsMode=new ComboBox();readonly TextBox reference=new TextBox();
  readonly Dictionary<string,TextBox> numbers=new Dictionary<string,TextBox>();readonly Dictionary<string,Control[]> rows=new Dictionary<string,Control[]>();
  public WizardSourceEditor(SourceSettings value){if(value==null)throw new ArgumentNullException("value");source=value;Dock=DockStyle.Fill;AutoScroll=true;BackColor=Color.White;ForeColor=Color.Black;
   table.AutoSize=true;table.Dock=DockStyle.Top;table.ColumnCount=2;table.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,290));table.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));Controls.Add(table);
   model.DropDownStyle=basis.DropDownStyle=ComboBoxStyle.DropDownList;model.Items.AddRange(new object[]{SourceModel.Rede,SourceModel.GeradorSincrono,SourceModel.ImpedanciaDefinida,SourceModel.UPS});basis.Items.AddRange(new object[]{SourceCurrentBasis.ReferidaBT,SourceCurrentBasis.RedeMT});
   Row("Model","Modelo da fonte",model);Number("Voltage","Tensão entre fases (V)");Number("Factor","Fator de tensão");Number("Drop","Queda máxima acumulada (%)");Number("PF","Fator de potência alvo");Row("Basis","Base da corrente da rede",basis);Number("Ik","Curto trifásico da rede (kA)");Number("RX","R/X da rede");Number("MV","Tensão da rede MT (V)");Number("KvaT","Transformador (kVA; 0=sem)");Number("Uk","Impedância uk do transformador (%)");Number("Loss","Perdas no cobre do transformador (kW)");
   Number("KvaG","Gerador — potência nominal (kVA)");Number("Xd","Gerador — Xd'' (%)");Number("RG","Gerador — resistência por fase (Ω)");upsMode.DropDownStyle=ComboBoxStyle.DropDownList;upsMode.Items.AddRange(new object[]{UPSOperatingMode.Inversor,UPSOperatingMode.Bypass});Row("UPSMode","UPS — modo declarado",upsMode);Number("UPSKva","UPS — potência nominal (kVA)");Number("UPSLimit","UPS — limite declarado do inversor (kA)");Number("UPSSeconds","UPS — duração declarada do limite (s)");
   Number("PhaseR","Fonte definida — R por fase (Ω)");Number("PhaseX","Fonte definida — X por fase (Ω)");Number("NeutralR","Fonte definida — R neutro (Ω)");Number("NeutralX","Fonte definida — X neutro (Ω)");Number("PER","Fonte definida — R PE (Ω)");Number("PEX","Fonte definida — X PE (Ω)");Row("Reference","Fonte / referência dos dados",reference);
   model.SelectedIndexChanged+=delegate{RefreshVisibility();};basis.SelectedIndexChanged+=delegate{RefreshVisibility();};upsMode.SelectedIndexChanged+=delegate{RefreshVisibility();};Reload();
  }
  void Row(string key,string title,Control input){int index=table.RowCount++;var label=new Label{Text=title,AutoSize=true,MaximumSize=new Size(280,0),Anchor=AnchorStyles.Left,ForeColor=Color.Black};input.Dock=DockStyle.Fill;input.Margin=new Padding(4,7,4,7);input.ForeColor=Color.Black;table.RowStyles.Add(new RowStyle(SizeType.Absolute,48));table.Controls.Add(label,0,index);table.Controls.Add(input,1,index);rows.Add(key,new[]{label,input});}
  void Number(string key,string title){var box=new TextBox();numbers.Add(key,box);Row(key,title,box);}
  void Put(string key,double value){numbers[key].Text=value.ToString("R",CultureInfo.CurrentCulture);}
  double Get(string key){double value;string text=numbers[key].Text.Trim();if(text.Contains(",")&&text.Contains("."))throw new InvalidDataException("Número ambíguo: "+text);if(!Double.TryParse(text.Replace(',','.'),NumberStyles.Float,CultureInfo.InvariantCulture,out value)||Double.IsNaN(value)||Double.IsInfinity(value))throw new InvalidDataException("Confira o valor de "+rows[key][0].Text+".");return value;}
  void VisibleRow(string key,bool visible){Control[] row=rows[key];foreach(Control c in row)c.Visible=visible;table.RowStyles[table.GetRow(row[0])].Height=visible?48:0;}
  void RefreshVisibility(){SourceModel selected=model.SelectedItem is SourceModel?(SourceModel)model.SelectedItem:SourceModel.Rede;bool generator=selected==SourceModel.GeradorSincrono,defined=selected==SourceModel.ImpedanciaDefinida,ups=selected==SourceModel.UPS;bool inverter=ups&&(!(upsMode.SelectedItem is UPSOperatingMode)||(UPSOperatingMode)upsMode.SelectedItem==UPSOperatingMode.Inversor);bool network=!generator&&!defined&&!inverter;bool mv=basis.SelectedItem is SourceCurrentBasis&&(SourceCurrentBasis)basis.SelectedItem==SourceCurrentBasis.RedeMT;
   foreach(string k in new[]{"Basis","Ik","RX","KvaT","Uk","Loss"})VisibleRow(k,network);VisibleRow("MV",network&&mv);foreach(string k in new[]{"KvaG","Xd","RG"})VisibleRow(k,generator);foreach(string k in new[]{"UPSMode","UPSKva"})VisibleRow(k,ups);foreach(string k in new[]{"UPSLimit","UPSSeconds"})VisibleRow(k,inverter);foreach(string k in new[]{"PhaseR","PhaseX","NeutralR","NeutralX","PER","PEX"})VisibleRow(k,defined);VisibleRow("Factor",!inverter);
  }
  void PutOptional(string key,double? value){numbers[key].Text=value.HasValue?value.Value.ToString("R",CultureInfo.CurrentCulture):"";}
  double? GetOptional(string key){return String.IsNullOrWhiteSpace(numbers[key].Text)?(double?)null:Get(key);}
  public void Reload(){upsMode.SelectedItem=source.UPSMode;Put("UPSKva",source.UPSRatedKva);Put("UPSLimit",source.UPSCurrentLimitKA);Put("UPSSeconds",source.UPSCurrentLimitSeconds);PutOptional("PhaseR",source.DefinedPhaseROhm);PutOptional("PhaseX",source.DefinedPhaseXOhm);PutOptional("NeutralR",source.DefinedNeutralROhm);PutOptional("NeutralX",source.DefinedNeutralXOhm);PutOptional("PER",source.DefinedPEROhm);PutOptional("PEX",source.DefinedPEXOhm);model.SelectedItem=source.Model;basis.SelectedItem=source.CurrentBasis;reference.Text=source.NetworkReference;Put("Voltage",source.LineVoltage);Put("Factor",source.VoltageFactor);Put("Drop",source.MaxDropPercent);Put("PF",source.TargetPowerFactor);Put("Ik",source.ShortCircuitKA);Put("RX",source.RXRatio);Put("MV",source.UpstreamVoltageV);Put("KvaT",source.TransformerKva);Put("Uk",source.TransformerUkPercent);Put("Loss",source.TransformerCopperLossKw);Put("KvaG",source.GeneratorRatedKva);Put("Xd",source.GeneratorXdPercent);Put("RG",source.GeneratorROhm);RefreshVisibility();}
  public void Commit(){if(!(model.SelectedItem is SourceModel))throw new InvalidDataException("Selecione o modelo da fonte.");source.Model=(SourceModel)model.SelectedItem;source.LineVoltage=Get("Voltage");source.VoltageFactor=Get("Factor");source.MaxDropPercent=Get("Drop");source.TargetPowerFactor=Get("PF");Project.Range(source.MaxDropPercent,.01,100,"limite de queda");Project.Range(source.TargetPowerFactor,.001,1,"FP alvo");source.NetworkReference=reference.Text;
   bool network=true;
   if(source.Model==SourceModel.GeradorSincrono){source.GeneratorRatedKva=Get("KvaG");source.GeneratorXdPercent=Get("Xd");source.GeneratorROhm=Get("RG");network=false;}
   if(source.Model==SourceModel.ImpedanciaDefinida){source.DefinedPhaseROhm=GetOptional("PhaseR");source.DefinedPhaseXOhm=GetOptional("PhaseX");source.DefinedNeutralROhm=GetOptional("NeutralR");source.DefinedNeutralXOhm=GetOptional("NeutralX");source.DefinedPEROhm=GetOptional("PER");source.DefinedPEXOhm=GetOptional("PEX");network=false;}
   if(source.Model==SourceModel.UPS){if(!(upsMode.SelectedItem is UPSOperatingMode))throw new InvalidDataException("Selecione o modo UPS.");source.UPSMode=(UPSOperatingMode)upsMode.SelectedItem;source.UPSRatedKva=Get("UPSKva");if(source.UPSMode==UPSOperatingMode.Inversor){source.UPSCurrentLimitKA=Get("UPSLimit");source.UPSCurrentLimitSeconds=Get("UPSSeconds");network=false;}}
   if(network){if(!(basis.SelectedItem is SourceCurrentBasis))throw new InvalidDataException("Selecione a base da corrente da rede.");source.CurrentBasis=(SourceCurrentBasis)basis.SelectedItem;source.ShortCircuitKA=Get("Ik");source.RXRatio=Get("RX");source.UpstreamVoltageV=source.CurrentBasis==SourceCurrentBasis.RedeMT?Get("MV"):0;source.TransformerKva=Get("KvaT");source.TransformerUkPercent=Get("Uk");source.TransformerCopperLossKw=Get("Loss");}
   else{source.ShortCircuitKA=0;source.TransformerKva=0;source.CurrentBasis=SourceCurrentBasis.ReferidaBT;}
   source.ValidateNetwork();
  }
 }
}
